#include "api_diagnostics.hpp"
#include <algorithm>
#include <map>
#include <mutex>
namespace scratchbird::engine::internal_api { namespace { std::mutex mu; using D=scratchbird::engine::sblr::SblrBridgeHealthDescriptorV1; std::map<std::string,D>live,used; std::string key(const D&d){return{(const char*)d.body.data(),d.body.size()};} bool tag(const EngineRequestContext&c,const char*x){return c.security_context_present&&std::find(c.trace_tags.begin(),c.trace_tags.end(),x)!=c.trace_tags.end();} EngineApiDiagnostic dg(std::string a,std::string b){return MakeEngineApiDiagnostic(std::move(a),std::move(b),{});} }
SblrBridgeHealthCoordinationResult CompileSblrBridgeHealthDescriptor(const EngineRequestContext&c,const std::string&n,std::uint64_t g){std::lock_guard l(mu);SblrBridgeHealthCoordinationResult o;if(!tag(c,"private_bridge_health_binder")||!tag(c,"sysarch_authorized")||!c.statement_metadata_snapshot_engine_owned||n!=c.statement_uuid.canonical||!g||!tag(c,"cluster_provider_admitted")||!tag(c,"cluster_route_fence_admitted")){o.diagnostic=dg("CLUSTER.GATEWAY_CLUSTER_FALLTHROUGH_FORBIDDEN","sblr.bridge_health.cluster_gate");return o;}o.descriptor.body[0]=1;o.descriptor.body[16]=1;for(int i=0;i<8;++i)o.descriptor.body[72+i]=(std::uint8_t)(g>>(8*i));live[key(o.descriptor)]=o.descriptor;o.ok=true;o.diagnostic=dg("OK","ok");return o;}
SblrBridgeHealthCoordinationResult ConsumeSblrBridgeHealthDescriptor(const EngineRequestContext&c,const D&x){std::lock_guard l(mu);SblrBridgeHealthCoordinationResult o;auto k=key(x);if(!tag(c,"private_bridge_health")){o.diagnostic=dg("SECURITY.ACCESS_DENIED","sblr.bridge_health.hidden");return o;}auto i=live.find(k);if(i==live.end()){o.diagnostic=used.count(k)?dg("MGA.TRANSACTION.STALE","sblr.bridge_health.stale"):dg("SECURITY.ACCESS_DENIED","sblr.bridge_health.hidden");return o;}if(c.query_cancellation_requested&&c.query_cancellation_requested()){o.diagnostic=dg("PROCESS.CANCELLED","sblr.bridge_health.cancelled");return o;}used[k]=x;live.erase(i);o.ok=true;o.descriptor=x;o.diagnostic=dg("OK","ok");return o;}}
